{
  "findings": [
    {
      "check_id": "CKV2_AZURE_31",
      "title": "Ensure VNET subnet is configured with a Network Security Group (NSG)",
      "resource": "azurerm_subnet.private_subnet",
      "severity": "MEDIUM",
      "explanation": "The subnet 'private_subnet' does not have a network_security_group_id associated with it. Without an NSG, the subnet lacks necessary traffic filtering controls, potentially exposing resources within this private subnet to unauthorized lateral movement or external access if other network boundaries are misconfigured."
    }
  ],
  "patched_code": "resource \"azurerm_subnet\" \"private_subnet\" {\n  name                      = \"smart-manufacturing-iot-monitoring-platform-subnet-private\"\n  resource_group_name       = azurerm_resource_group.smart_manufacturing.name\n  virtual_network_name      = azurerm_virtual_network.smart_manufacturing_vnet.name\n  address_prefixes          = [\"10.0.2.0/24\"]\n  network_security_group_id = azurerm_network_security_group.example.id\n}\n\n# Note: The user must ensure that 'azurerm_network_security_group.example' exists in their configuration.\n# If it does not exist, please create it or reference an existing NSG ID.",
  "fix_summary": "Added the `network_security_group_id` attribute to the `azurerm_subnet` resource to associate it with a Network Security Group, satisfying CKV2_AZURE_31. A comment was added to remind the user to define or reference the actual NSG resource."
}
